/**
 * Generate EleutherAI lm-evaluation-harness task YAMLs for TenkiBench.
 *
 * Produces:
 *   lm-eval-tenkibench/tasks/tenkibench_<bench>.yaml   — one per bench
 *   lm-eval-tenkibench/tasks/tenkibench.yaml           — root task (includes group)
 *   lm-eval-tenkibench/group.yaml                      — alias grouping all benches
 *
 * Reads:
 *   tasks/<bench>/<category>/<id>.yaml — to discover which benches exist
 *
 * The generated files are committed to git so end-users don't need
 * Node/TypeScript to use the adapter — only Python + lm-eval.
 *
 * Run with:  pnpm generate:lm-eval   (or `npx tsx scripts/generate-lm-eval-tasks.ts`)
 */
import { mkdirSync, readdirSync, statSync, writeFileSync, rmSync, existsSync } from "node:fs";
import { join } from "node:path";

const REPO_ROOT = process.cwd();
const TASKS_DIR = join(REPO_ROOT, "tasks");
const OUT_DIR = join(REPO_ROOT, "lm-eval-tenkibench");
const OUT_TASKS_DIR = join(OUT_DIR, "tasks");

const HF_DATASET_PATH = "tenki-labs/tenkibench";

interface BenchInfo {
  /** Folder slug, e.g. "norwegian-smb" */
  slug: string;
  /** Underscore form used inside lm-eval task names + HF config name */
  underscore: string;
  /** HF dataset config name — matches the export-hf.ts output */
  hfConfig: string;
  /** Number of categories (folders) under tasks/<slug>/ */
  categoryCount: number;
}

function discoverBenches(): BenchInfo[] {
  if (!existsSync(TASKS_DIR)) {
    throw new Error(`tasks directory not found at ${TASKS_DIR}`);
  }
  const entries = readdirSync(TASKS_DIR, { withFileTypes: true });
  const benches: BenchInfo[] = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const slug = entry.name;
    const benchPath = join(TASKS_DIR, slug);
    const subdirs = readdirSync(benchPath, { withFileTypes: true })
      .filter((e) => e.isDirectory());
    if (subdirs.length === 0) continue;
    benches.push({
      slug,
      underscore: slug.replace(/-/g, "_"),
      hfConfig: slug, // matches data/<slug>/train.jsonl in HF dataset
      categoryCount: subdirs.length,
    });
  }
  return benches.sort((a, b) => a.slug.localeCompare(b.slug));
}

/**
 * lm-eval-harness task YAML. Schema reference:
 *   github.com/EleutherAI/lm-evaluation-harness/blob/main/docs/new_task_guide.md
 *
 * Key fields:
 *   - task: unique name
 *   - dataset_path: HF Hub repo ID
 *   - dataset_name: HF config name
 *   - test_split: which split to evaluate (TenkiBench publishes only "train")
 *   - output_type: "generate_until" — model produces free-form text
 *   - doc_to_text: jinja template that produces the prompt
 *   - doc_to_target: jinja template producing the reference answer
 *   - process_results: !function utils.process_results — custom scorer
 */
function buildTaskYaml(bench: BenchInfo): string {
  return `# Auto-generated by scripts/generate-lm-eval-tasks.ts — do not edit by hand.
# Re-run \`pnpm generate:lm-eval\` after changing the bench list.

task: tenkibench_${bench.underscore}
dataset_path: ${HF_DATASET_PATH}
dataset_name: ${bench.hfConfig}
test_split: train

output_type: generate_until

# Build the prompt from system_prompt + user_prompt. Empty system_prompt is
# common (Tenki tasks declare it conditionally), so we render an empty line
# only when present.
doc_to_text: !function utils.doc_to_text
doc_to_target: "{{gold_answer}}"

# We capture only the surface fields here. The full evaluation logic
# (regex patterns, JSON schemas, LLM-judge rubrics, tolerances) is
# implemented in utils.tenkibench_score and runs against eval_method.
process_results: !function utils.process_results

generation_kwargs:
  max_gen_toks: 1024
  temperature: 0.0
  do_sample: false
  until:
    - "\\n\\n---\\n\\n"

metric_list:
  - metric: tenkibench_score
    aggregation: mean
    higher_is_better: true

metadata:
  version: 0.1
  bench: ${bench.slug}
  homepage: https://bench.tenki.no
`;
}

function buildRootTaskYaml(benches: BenchInfo[]): string {
  // The root "tenkibench" file is just an alias to the group (group.yaml).
  // lm-eval will pick up either path when --tasks tenkibench is passed.
  const list = benches.map((b) => `  - tenkibench_${b.underscore}`).join("\n");
  return `# Auto-generated by scripts/generate-lm-eval-tasks.ts — do not edit by hand.
#
# Root TenkiBench task — runs all benches and reports a single aggregate
# tenkibench_score (weighted mean across benches).
#
# Usage:
#   lm_eval --model hf \\
#     --model_args pretrained=mistralai/Mistral-Nemo-Instruct-2407 \\
#     --tasks tenkibench \\
#     --include_path .

group: tenkibench
task:
${list}

aggregate_metric_list:
  - metric: tenkibench_score
    aggregation: mean
    weight_by_size: true
    higher_is_better: true

metadata:
  version: 0.1
  homepage: https://bench.tenki.no
`;
}

function buildGroupYaml(benches: BenchInfo[]): string {
  const list = benches.map((b) => `  - tenkibench_${b.underscore}`).join("\n");
  return `# Auto-generated by scripts/generate-lm-eval-tasks.ts — do not edit by hand.
#
# Group definition — lets users pass --tasks tenkibench and have all 11
# bench tasks resolved as a unit.

group: tenkibench
task:
${list}

aggregate_metric_list:
  - metric: tenkibench_score
    aggregation: mean
    weight_by_size: true
    higher_is_better: true

metadata:
  version: 0.1
`;
}

function main(): void {
  console.log("Discovering benches under tasks/ ...");
  const benches = discoverBenches();
  console.log(`  ${benches.length} benches found:`);
  for (const b of benches) {
    console.log(`    - ${b.slug} (${b.categoryCount} categories)`);
  }

  // Clean tasks/ subdirectory so removed benches don't linger
  if (existsSync(OUT_TASKS_DIR)) {
    for (const f of readdirSync(OUT_TASKS_DIR)) {
      if (f.startsWith("tenkibench") && f.endsWith(".yaml")) {
        rmSync(join(OUT_TASKS_DIR, f));
      }
    }
  }
  mkdirSync(OUT_TASKS_DIR, { recursive: true });

  for (const bench of benches) {
    const path = join(OUT_TASKS_DIR, `tenkibench_${bench.underscore}.yaml`);
    writeFileSync(path, buildTaskYaml(bench), "utf8");
    console.log(`  wrote ${path}`);
  }

  const rootPath = join(OUT_TASKS_DIR, "tenkibench.yaml");
  writeFileSync(rootPath, buildRootTaskYaml(benches), "utf8");
  console.log(`  wrote ${rootPath}`);

  const groupPath = join(OUT_DIR, "group.yaml");
  writeFileSync(groupPath, buildGroupYaml(benches), "utf8");
  console.log(`  wrote ${groupPath}`);

  console.log(`\nGenerated ${benches.length + 1} task YAMLs + group.yaml`);
}

main();
